  Variables (m0 : fmem) (S DT DST dcap lo : Z) (bs : list Z) (dt : dtable) (fmw : word) (jd j1 j2 jb : list byte).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Notation tl := (dt_tableLog dt).
  (* [comment removed for export] *)
  Hypothesis FR2 : rw_cells psegs m0 (SP + 16) [CB 16 j2].
  Hypothesis FR1 : rw_cells psegs m0 (SP + 32) [CB 16 j1].
  Hypothesis FRB : rw_cells psegs m0 (SP + 48) [CB 40 jb].
  (* [comment removed for export] *)
  Hypothesis DTH : rw_cells psegs m0 DT [C2 (Z_to_bv 64 tl); C2 fmw].
  Hypothesis TBB : bytes_at psegs m0 (DT + 4) (concat (map fse_cell_bytes (dt_cells dt))).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HCELLS : zlen (dt_cells dt) = 2^tl.
  Hypothesis HCOK : cells_ok tl (dt_cells dt).
  (* [comment removed for export] *)
  Hypothesis SRC : bytes_at psegs m0 S (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.
  Hypothesis OUTA : u8arr psegs m0 DST jd.
  Hypothesis LJD : zlen jd = dcap.
  Hypothesis STK : stk psegs m0 lo SP.
  Hypothesis MI : mem_inv psegs m0.
  (* [comment removed for export] *)
  Hypothesis LOSP : lo <= SP.
