  Hypothesis SP47 : SP + 160 <= 2^47.
  Hypothesis HS : 8 <= S /\ S + zlen bs <= lo.
  Hypothesis HDT : 0 < DT /\ DT mod 4 = 0 /\ DT + 4 + 4 * 2^tl <= lo.
  Hypothesis HDST : 3 <= DST /\ DST + dcap <= lo /\ 0 <= dcap <= 255.
  Hypothesis DJ1 : DST + dcap <= DT \/ DT + 4 + 4 * 2^tl <= DST.
  Hypothesis DJ2 : DST + dcap <= S \/ S + zlen bs <= DST.
  Hypothesis DJ3 : DT + 4 + 4 * 2^tl <= S \/ S + zlen bs <= DT.

  Notation WF := [(SP + 16, SP + 88); (DST, DST + dcap)].

  Lemma fast_main : forall m1 d3 s1 s2 r (wc wb wp : word) (jp : list byte) (x8 x9 x18 x22 x29 x30 x31 : word) (P2 P3 : Z),
    P2 = S + bd_ptr d3 -> P3 = S ->
    (let! x := main_loop bs dt dcap true (Datatypes.S (Z.to_nat dcap)) (mkDec [] s1 s2 d3) in
     tail_loop bs dt dcap true (Datatypes.S (Z.to_nat dcap)) x) = r -> res_ok r ->
    bitd_ok bs d3 -> bd_bits d3 <= 64 -> bd_zero d3 = false ->
    rw_cells psegs m1 (SP + 16) [C8 (Z_to_bv 64 s2); C8 (Z_to_bv 64 (DT + 4))] ->
    rw_cells psegs m1 (SP + 32) [C8 (Z_to_bv 64 s1); C8 (Z_to_bv 64 (DT + 4))] ->
    rw_cells psegs m1 (SP + 48) [C8 wc; C4 wb; CB 4 jp; C8 wp; C8 (Z_to_bv 64 S); C8 (Z_to_bv 64 (S + 8))] ->
    hk (bytes_at psegs m1 (DT + 4) (concat (map fse_cell_bytes (dt_cells dt)))) ->
    bytes_at psegs m1 S (map (Z_to_bv 8) bs) -> u8arr psegs m1 DST jd ->
    munch WF m0 m1 -> wmono psegs m0 m1 -> mem_inv psegs m1 -> stk psegs m1 lo SP -> safe_K sp gp tp F fc x24 x25 x26 x27 m0 DST dcap lo POST r ->
    evt psegs POST (MS (mkR (Z_to_bv 64 0x1c0d8) sp gp tp (Z_to_bv 64 s1) (Z_to_bv 64 s2) (Z_to_bv 64 DST) x8 x9
                            (Z_to_bv 64 (S + 8)) (Z_to_bv 64 P2) (Z_to_bv 64 P3) (Z_to_bv 64 (bd_bits d3))
                            (Z_to_bv 64 ZEROFILLED_F) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (bd_cont d3)) x18
                            (Z_to_bv 64 DST) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) x22 x23 x24 x25 x26 x27
                            (Z_to_bv 64 64) x29 x30 x31)
                       F (Z_to_bv 64 0x1c704) fc None m1 (seg_rom psegs)).
