  (* [comment removed for export] *)
  Ltac to_mainf d3 RL ROK K MU0 WM0 v1 v2 r :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    unfold hk in TBB, DJ1;
    let TB1 := fresh "TB1" in
    assert (TB1 : bytes_at psegs mm (DT + 4) (concat (map fse_cell_bytes (dt_cells dt))))
      by (apply (bytes_at_transport psegs _ m0 mm _ _ TBB MU0); cbn [disjoint_from]; rewrite fse_cells_length; lia);
    change (hk (bytes_at psegs m0 (DT + 4) (concat (map fse_cell_bytes (dt_cells dt))))) in TBB;
    change (hk (bytes_at psegs mm (DT + 4) (concat (map fse_cell_bytes (dt_cells dt))))) in TB1;
    change (hk (DST + dcap <= DT \/ DT + 4 + 4 * 2^tl <= DST)) in DJ1;
    eapply (fast_main mm d3 v1 v2 r);
      [cbn [bd_ptr]; lia| lia| exact RL| exact ROK| | cbn [bd_bits]; lia| first [reflexivity| eassumption]| eassumption| eassumption|
       eassumption| exact TB1| eassumption| eassumption| exact MU0| exact WM0| eassumption| eassumption| exact K]
    end.

  (* [comment removed for export] *)
  Lemma fast_post : forall m1 d0 jp r (y1 x5 x6 x7 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x22 x28 x29 x30 x31 : word),
    init_dstream bs = Ok d0 -> decompress_usingDTable bs dt dcap true = r -> res_ok r ->
    rw_cells psegs m1 (SP + 48) (bitdz_cells S d0 jp) ->
    rw_cells psegs m1 (SP + 32) [CB 16 j1] -> rw_cells psegs m1 (SP + 16) [CB 16 j2] ->
    rw_cells psegs m1 DT [C2 (Z_to_bv 64 tl); C2 fmw] ->
    bytes_at psegs m1 S (map (Z_to_bv 8) bs) -> u8arr psegs m1 DST jd ->
    munch WF m0 m1 -> wmono psegs m0 m1 -> mem_inv psegs m1 -> stk psegs m1 lo SP ->
    safe_K sp gp tp F fc x24 x25 x26 x27 m0 DST dcap lo POST r ->
    evt psegs POST (MS (mkR y1 sp gp tp x5 x6 x7 (Z_to_bv 64 DT) x9 x10 x11 x12 x13 x14 x15 x16 x17 x18
                            (Z_to_bv 64 DST) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) x22 x23 x24 x25 x26 x27
                            x28 x29 x30 x31)
