  (* [comment removed for export] *)
  Ltac hb10_big r :=
    zstep; zstep; zstep; brute_reg 10%Z r 1 255 sm1;
    zstep; zstep; zstep; brute_reg 10%Z r 1 255 sm2;
    zstep; zstep; brute_reg 10%Z r 1 255 sm3;
    zstep; brute_reg 10%Z r 1 255 nsm;
    zstep; zstep; zstep; zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_a (nsm r0));
    zstep; zstep; zstep; zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_b (pc_a (nsm r0)));
    zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_c (pc_b (pc_a (nsm r0))));
    zstep; zstep; zstep; zstep; zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_d (pc_c (pc_b (pc_a (nsm r0)))));
    zstep; brute_reg 10%Z r 1 255 (fun r0 => 31 - Z.log2 r0);
    zstep; brute_reg 10%Z r 1 255 (fun r0 => Z.log2 r0);
    zstep; brute_reg 12%Z r 1 255 (fun r0 => 8 - Z.log2 r0).

  (* [comment removed for export] *)
  Ltac hb10_small r N :=
    zstep; zstep; zstep; brute_reg 10%Z r 1 255 sm1;
    zstep; zstep; zstep; brute_reg 10%Z r 1 255 sm2;
    zstep; zstep; brute_reg 10%Z r 1 255 sm3;
    zstep; brute_reg 10%Z r 1 255 nsm;
    zstep; zstep; zstep; zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_a (nsm r0));
    zstep; zstep; zstep; zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_b (pc_a (nsm r0)));
    zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_c (pc_b (pc_a (nsm r0))));
    zstep; zstep; zstep; zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => pc_d (pc_c (pc_b (pc_a (nsm r0)))));
    zstep; brute_reg 10%Z r 1 255 (fun r0 => 31 - Z.log2 r0);
    zstep; zstep; zstep; brute_reg 10%Z r 1 255 (fun r0 => 72 - Z.log2 r0 - 8 * N).

  Lemma fast_run : forall r (x5 x6 x7 x10 x12 x13 x15 x16 x17 x22 x28 x29 x30 x31 : word) (X1 X2 : Z),
    0 <= X1 < 2^64 -> 0 <= X2 < 2^64 -> X2 + X1 = S + zlen bs ->
    decompress_usingDTable bs dt dcap true = r -> res_ok r ->
    safe_K sp gp tp F fc x24 x25 x26 x27 m0 DST dcap lo POST r ->
    evt psegs POST (MS (mkR ra sp gp tp x5 x6 x7 (Z_to_bv 64 DT) (Z_to_bv 64 X1) x10 (Z_to_bv 64 S) x12 x13
                            (Z_to_bv 64 (zlen bs)) x15 x16 x17 (Z_to_bv 64 X2) (Z_to_bv 64 DST) (Z_to_bv 64 (DST + dcap))
                            (Z_to_bv 64 (DST + dcap - 3)) x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
